      if (dispatchers !== null && dispatchers.length === 0) {
        throw new Error(
          `${init.session} runs as the worker "${worker}" and its launch published neither Agent nor ` +
            `Task (${init.tools.length} tools; of the provider's own delegation: ` +
            `${JSON.stringify(init.offered)}) — every agent keeps its provider's own sub-agents, ` +
            'so this is the app withholding it, not the provider choosing',
        )
      }
