      await waitFor(
        'the conversation to settle',
        async () => {
          const now = await snapshot()
          assertHistoryAvailable(now, 'the conversation to settle')
          return now.turns >= 1 && now.status === 'idle' ? now : null
        },
        TURN_BUDGET_MS,
      )

